import 'package:flutter/material.dart';
import '../services/krevzy_social_settings_service.dart';
class NotificationSettingsScreen extends StatefulWidget{const NotificationSettingsScreen({super.key});@override State<NotificationSettingsScreen>createState()=>_NotificationSettingsScreenState();}
class _NotificationSettingsScreenState extends State<NotificationSettingsScreen>{bool enabled=true,messages=true,sound=true,vibration=true,loading=true;@override void initState(){super.initState();_load();}Future<void>_load()async{try{final d=await KrevzySocialSettingsService.getSettings();if(!mounted)return;setState((){enabled=d['notifications_enabled']as bool? ?? true;messages=d['message_notifications']as bool? ?? true;sound=d['notification_sound']as bool? ?? true;vibration=d['notification_vibration']as bool? ?? true;loading=false;});}catch(e){if(mounted)setState(()=>loading=false);}}Future<void>_save(String k,bool v)async{setState((){if(k=='notifications_enabled')enabled=v;if(k=='message_notifications')messages=v;if(k=='notification_sound')sound=v;if(k=='notification_vibration')vibration=v;});try{await KrevzySocialSettingsService.setValue(k,v);}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('Unable to save: $e')));}}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Notification settings')),body:loading?const Center(child:CircularProgressIndicator()):ListView(children:[SwitchListTile(title:const Text('Notifications'),value:enabled,onChanged:(v)=>_save('notifications_enabled',v)),SwitchListTile(title:const Text('Message notifications'),value:messages,onChanged:enabled?(v)=>_save('message_notifications',v):null),SwitchListTile(title:const Text('Notification sound'),value:sound,onChanged:enabled?(v)=>_save('notification_sound',v):null),SwitchListTile(title:const Text('Vibration'),value:vibration,onChanged:enabled?(v)=>_save('notification_vibration',v):null)]));}
